1	/**
2	 * Client-side notification cache, keyed by organization.
3	 *
4	 * The bell in the top bar and the inbox list are rendered in different parts
5	 * of the tree but must agree on the unread count the instant something is
6	 * marked read. A per-org external store gives them one copy of the truth
7	 * between server revalidations; switching tenants simply reads a different
8	 * key rather than leaking rows across the boundary.
9	 */
10	import { toIsoTimestamp } from "@/types/common";
11	import type { NotificationId, OrgId } from "@/types/common";
12	import type { Notification } from "@/types/notification";
13	
14	type Listener = () => void;
15	
16	const byOrg = new Map<string, readonly Notification[]>();
