let registered = false;

/**
 * Builds the in-app path to an issue's detail page (`/org/projects/project/issues/number`).
 * Returns `null` when the org, project or issue has since disappeared, so
 * callers can skip the notification rather than write a dead link.
 */
async function issueHref(
  orgId: OrgId,
  projectId: ProjectId,
  issueId: IssueId,
): Promise<string | null> {
  const [org, project, issue] = await Promise.all([
    orgRepo.findOrgById(orgId),
    projectRepo.findProjectById(orgId, projectId),
    issueRepo.findIssueById(orgId, issueId),
  ]);
  if (!org || !project || !issue) return null;
  return `/${org.slug}/projects/${project.slug}/issues/${issue.number}`;
}

function registerFanOut(): void {
  if (registered) return;
  registered = true;

  subscribe("issue.created", async (payload) => {
    if (payload.assigneeId === null) return;
    const href = await issueHref(payload.orgId, payload.projectId, payload.issueId);
    if (href === null) return;
    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${payload.issueId} is now yours`,
      href,
      actorId: payload.actorId,
    });
  });

  subscribe("issue.assigned", async (payload) => {
    const href = await issueHref(payload.orgId, payload.projectId, payload.issueId);
    if (href === null) return;
    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${payload.issueId} is now yours`,
      href,
      actorId: payload.actorId,
    });
  });

  subscribe("issue.status_changed", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue || issue.assigneeId === null) return;
    const href = await issueHref(payload.orgId, payload.projectId, payload.issueId);
    if (href === null) return;
    await notify(payload.orgId, "issue_status_changed", [issue.assigneeId], {
      title: "Issue status changed",
      body: `Issue ${payload.issueId} moved from ${payload.from} to ${payload.to}`,
      href,
      actorId: payload.actorId,
    });
  });

  subscribe("issue.overdue", async (payload) => {
    if (payload.assigneeId === null) return;
    const href = await issueHref(payload.orgId, payload.projectId, payload.issueId);
    if (href === null) return;
    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
      title: "An issue is overdue",
      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
      href,
      actorId: null,
    });
  });

  subscribe("comment.created", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue) return;
    const href = await issueHref(payload.orgId, issue.projectId, payload.issueId);
    if (href === null) return;

    const watchers = [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])];

    await notify(payload.orgId, "comment_created", watchers, {
      title: "New comment",
      body: `A comment was added to issue ${payload.issueId}`,
      href,
      actorId: payload.actorId,
    });

    if (payload.mentionedUserIds.length > 0) {
      await notify(
        payload.orgId,
        "comment_mention",
        payload.mentionedUserIds,
        {
          title: "You were mentioned",
          body: `You were mentioned on issue ${payload.issueId}`,
          href,
          actorId: payload.actorId,
        },
      );
    }
  });

  // The owner is told about every new member; the person who joined already
  // knows — they are the one who just accepted the invitation.
  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    await notify(payload.orgId, "member_joined", [org.ownerId], {
      title: "A new member joined",
      body: `${payload.userId} joined ${org.name} as ${payload.role}`,
      href: `/${org.slug}/settings/members`,
      actorId: payload.actorId,
    });
  });

  // Fired only when a write was actually refused for lack of plan room; the
  // periodic usage recount never emits this event, so it never lands here.
  // While the owner's alert for a resource is unread, further refusals for
  // that same resource are folded into it instead of piling up.
  subscribe("billing.limit_exceeded", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    const href = `/${org.slug}/settings/billing?resource=${payload.resource}`;

    const existing = await notificationRepo.findUnreadByHref(
      payload.orgId,
      org.ownerId,
      "plan_limit_reached",
      href,
    );
    if (existing) return;

    await notify(payload.orgId, "plan_limit_reached", [org.ownerId], {
      title: "Plan limit reached",
      body: `Your plan allows ${payload.limit} ${payload.resource}; ${payload.used} are in use`,
      href,
      actorId: null,
    });
  });
}

registerFanOut();

