/**
 * Resolves a search hit to the page the app actually serves. `null` means the
 * indexed subject (or its parent issue/project) is gone — the caller drops
 * the hit rather than link to a page that no longer exists.
 */
async function hrefFor(
  orgId: OrgId,
  orgSlug: string,
  row: Pick<SearchIndexRow, "subjectKind" | "subjectId">,
): Promise<string | null> {
  switch (row.subjectKind) {
    case "project": {
      const project = await projectRepo.findProjectById(
        orgId,
        row.subjectId as ProjectId,
      );
      return project ? `/${orgSlug}/projects/${project.slug}` : null;
    }
    case "issue": {
      const issue = await issueRepo.findIssueById(orgId, row.subjectId as IssueId);
      if (!issue) return null;
      return issueHrefFor(orgId, orgSlug, issue);
    }
    case "comment": {
      const comment = await commentRepo.findCommentById(
        orgId,
        row.subjectId as CommentId,
      );
      if (!comment) return null;
      const issue = await issueRepo.findIssueById(orgId, comment.issueId);
      if (!issue) return null;
      return issueHrefFor(orgId, orgSlug, issue);
    }
  }
}

async function issueHrefFor(
  orgId: OrgId,
  orgSlug: string,
  issue: Issue,
): Promise<string | null> {
  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  return project
    ? `/${orgSlug}/projects/${project.slug}/issues/${issue.number}`
    : null;
}

