1	/**
2	 * The fan-out hub: one domain event becomes in-app rows, an email draft and/or a digest entry, filtered by each recipient's preferences.
3	 *
4	 * Must call (do not reimplement): assertCan, assertOrgScope, isEnabled, subscribe
5	 */
6	import { subscribe } from "@/lib/event-bus";
7	import { isEnabled } from "@/lib/feature-flags";
8	import { assertCan } from "@/lib/permissions";
9	import { assertOrgScope } from "@/lib/tenant";
10	import * as issueRepo from "@/server/repositories/issue-repository";
11	import * as notificationRepo from "@/server/repositories/notification-repository";
12	import * as orgRepo from "@/server/repositories/organization-repository";
13	import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
14	import * as projectRepo from "@/server/repositories/project-repository";
15	import { toIsoTimestamp } from "@/types/common";
16	import { notificationResource, requireFound } from "./_support";
17	import type {
18	  ListNotificationsInput,
19	  MarkNotificationReadInput,
20	  UpdateNotificationPreferenceInput,
21	} from "@/schemas/notification";
22	import type { IssueId, OrgId, Page, ProjectId, UserId } from "@/types/common";
23	import type { FlagContext } from "@/types/feature-flag";
24	import type { Actor } from "@/types/member";
25	import type {
26	  Notification,
27	  NotificationChannel,
28	  NotificationKind,
29	  NotificationPreference,
30	} from "@/types/notification";
31	
32	export type NotificationPayload = {
33	  title: string;
34	  body: string;
35	  href: string;
36	  actorId: UserId | null;
37	};
38	
39	/** Channels used when a recipient has never touched their preferences. */
40	const DEFAULT_CHANNELS: readonly NotificationChannel[] = ["in_app", "email"];
41	
42	/**
43	 * Writes one notification row per recipient, each with the channel set that
44	 * recipient's preferences allow. A recipient who has muted every channel is
45	 * skipped entirely rather than given a row nobody will ever see.
46	 */
47	export async function notify(
48	  orgId: OrgId,
49	  kind: NotificationKind,
50	  recipients: readonly UserId[],
51	  payload: NotificationPayload,
52	): Promise<readonly Notification[]> {
53	  if (recipients.length === 0) return [];
54	
55	  const org = await orgRepo.findOrgById(orgId);
56	  const flags: FlagContext = {
57	    orgId,
58	    userId: payload.actorId,
59	    plan: org?.plan ?? "free",
60	    role: null,
61	    overrides: org?.settings.enabledFlagOverrides,
62	  };
63	
64	  const rows = [];
65	
66	  for (const recipientId of new Set(recipients)) {
67	    if (recipientId === payload.actorId) continue;
68	
69	    const preference = await preferenceRepo.getPreference(
70	      orgId,
71	      recipientId,
72	      kind,
73	    );
74	    const channels = resolveChannels(preference, flags);
75	    if (channels.length === 0) continue;
76	
77	    rows.push({
78	      orgId,
79	      recipientId,
80	      kind,
81	      title: payload.title,
82	      body: payload.body,
83	      href: payload.href,
84	      actorId: payload.actorId,
85	      channels,
86	    });
87	  }
88	
89	  return notificationRepo.insertNotifications(orgId, rows);
90	}
91	
92	export async function listNotifications(
93	  actor: Actor,
94	  input: ListNotificationsInput,
95	): Promise<Page<Notification>> {
96	  assertOrgScope(actor, input.orgId);
97	  assertCan(
98	    actor,
99	    "notification:read",
100	    notificationResource(input.orgId, input.recipientId),
101	  );
102	  return notificationRepo.listNotifications(input);
103	}
104	
105	export async function markRead(
106	  actor: Actor,
107	  input: MarkNotificationReadInput,
108	): Promise<Notification> {
109	  assertOrgScope(actor, input.orgId);
110	  assertCan(
111	    actor,
112	    "notification:manage",
113	    notificationResource(input.orgId, actor.userId),
114	  );
115	  return notificationRepo.markRead(
116	    input.orgId,
117	    actor.userId,
118	    input.notificationId,
119	    toIsoTimestamp(new Date()),
120	  );
121	}
122	
123	export async function markAllRead(
124	  actor: Actor,
125	  orgId: OrgId,
126	): Promise<number> {
127	  assertOrgScope(actor, orgId);
128	  assertCan(
129	    actor,
130	    "notification:manage",
131	    notificationResource(orgId, actor.userId),
132	  );
133	  return notificationRepo.markAllRead(
134	    orgId,
135	    actor.userId,
136	    toIsoTimestamp(new Date()),
137	  );
138	}
139	
140	export async function updatePreference(
141	  actor: Actor,
142	  input: UpdateNotificationPreferenceInput,
143	): Promise<NotificationPreference> {
144	  assertOrgScope(actor, input.orgId);
145	  assertCan(
146	    actor,
147	    "notification:manage",
148	    notificationResource(input.orgId, input.userId),
149	  );
150	  return preferenceRepo.upsertPreference(input);
151	}
152	
153	/**
154	 * Turns a stored preference into the channels one notification will use.
155	 * `digestOnly` suppresses the immediate email but keeps the in-app row, and
156	 * the email channel additionally requires the org's `digest_email` plan flag.
157	 */
158	export function resolveChannels(
159	  preference: NotificationPreference | null,
160	  flags: FlagContext,
161	): readonly NotificationChannel[] {
162	  if (preference === null) return DEFAULT_CHANNELS;
163	
164	  const channels: NotificationChannel[] = [];
165	  if (preference.inApp) channels.push("in_app");
166	
167	  const emailAllowed =
168	    preference.email &&
169	    (!preference.digestOnly || isEnabled("digest_email", flags));
170	
171	  if (emailAllowed) channels.push("email");
172	  return channels;
173	}
174	
175	/**
176	 * The bus wiring. Attached at module load rather than from `event-registry`
177	 * because the fan-out has no other public entry point — importing this module
178	 * is what makes an org start receiving notifications.
179	 */
180	let registered = false;
181	
182	/**
183	 * Builds the in-app path to an issue's detail page (`/org/projects/project/issues/number`).
184	 * Returns `null` when the org, project or issue has since disappeared, so
185	 * callers can skip the notification rather than write a dead link.
186	 */
187	async function issueHref(
188	  orgId: OrgId,
189	  projectId: ProjectId,
190	  issueId: IssueId,
191	): Promise<string | null> {
192	  const [org, project, issue] = await Promise.all([
193	    orgRepo.findOrgById(orgId),
194	    projectRepo.findProjectById(orgId, projectId),
195	    issueRepo.findIssueById(orgId, issueId),
196	  ]);
197	  if (!org || !project || !issue) return null;
198	  return `/${org.slug}/projects/${project.slug}/issues/${issue.number}`;
199	}
200	
201	function registerFanOut(): void {
202	  if (registered) return;
203	  registered = true;
204	
205	  subscribe("issue.created", async (payload) => {
206	    if (payload.assigneeId === null) return;
207	    const href = await issueHref(payload.orgId, payload.projectId, payload.issueId);
208	    if (href === null) return;
209	    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
210	      title: "You were assigned an issue",
211	      body: `Issue ${payload.issueId} is now yours`,
212	      href,
213	      actorId: payload.actorId,
214	    });
215	  });
216	
217	  subscribe("issue.assigned", async (payload) => {
218	    const href = await issueHref(payload.orgId, payload.projectId, payload.issueId);
219	    if (href === null) return;
220	    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
221	      title: "You were assigned an issue",
222	      body: `Issue ${payload.issueId} is now yours`,
223	      href,
224	      actorId: payload.actorId,
225	    });
226	  });
227	
228	  subscribe("issue.status_changed", async (payload) => {
229	    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
230	    if (!issue || issue.assigneeId === null) return;
231	    const href = await issueHref(payload.orgId, payload.projectId, payload.issueId);
232	    if (href === null) return;
233	    await notify(payload.orgId, "issue_status_changed", [issue.assigneeId], {
234	      title: "Issue status changed",
235	      body: `Issue ${payload.issueId} moved from ${payload.from} to ${payload.to}`,
236	      href,
237	      actorId: payload.actorId,
238	    });
239	  });
240	
241	  subscribe("issue.overdue", async (payload) => {
242	    if (payload.assigneeId === null) return;
243	    const href = await issueHref(payload.orgId, payload.projectId, payload.issueId);
244	    if (href === null) return;
245	    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
246	      title: "An issue is overdue",
247	      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
248	      href,
249	      actorId: null,
250	    });
251	  });
252	
253	  subscribe("comment.created", async (payload) => {
254	    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
255	    if (!issue) return;
256	    const href = await issueHref(payload.orgId, issue.projectId, payload.issueId);
257	    if (href === null) return;
258	
259	    const watchers = [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])];
260	
261	    await notify(payload.orgId, "comment_created", watchers, {
262	      title: "New comment",
263	      body: `A comment was added to issue ${payload.issueId}`,
264	      href,
265	      actorId: payload.actorId,
266	    });
267	
268	    if (payload.mentionedUserIds.length > 0) {
269	      await notify(
270	        payload.orgId,
271	        "comment_mention",
272	        payload.mentionedUserIds,
273	        {
274	          title: "You were mentioned",
275	          body: `You were mentioned on issue ${payload.issueId}`,
276	          href,
277	          actorId: payload.actorId,
278	        },
279	      );
280	    }
281	  });
282	
283	  // The owner is told about every new member; the person who joined already
284	  // knows — they are the one who just accepted the invitation.
285	  subscribe("member.joined", async (payload) => {
286	    const org = requireFound(
287	      await orgRepo.findOrgById(payload.orgId),
288	      "Organization",
289	      payload.orgId,
290	    );
291	    await notify(payload.orgId, "member_joined", [org.ownerId], {
292	      title: "A new member joined",
293	      body: `${payload.userId} joined ${org.name} as ${payload.role}`,
294	      href: `/${org.slug}/settings/members`,
295	      actorId: payload.actorId,
296	    });
297	  });
298	
