1	import type { Actor, Role } from "@/types/member";
2	import { ROLE_RANK } from "@/types/member";
3	import type {
4	  PermissionAction,
5	  PermissionDecision,
6	  PermissionResource,
7	} from "@/types/permission";
8	
9	/**
10	 * The single authorization entry point for Taskflow.
11	 *
12	 * Every Server Action, service method, Route Handler and permission-sensitive
13	 * UI component funnels through `can()`. Nothing else may branch on
14	 * `actor.role` directly — if you find yourself writing `role === "admin"`,
15	 * add an action to `PermissionAction` and a row to `ROLE_MATRIX` instead.
16	 *
17	 * Decision order:
18	 *   1. cross-tenant guard (`actor.orgId` must equal `resource.orgId`)
19	 *   2. platform staff bypass
20	 *   3. role matrix lookup
21	 *   4. ownership escalations (authors edit their own issues/comments)
22	 */
23	
24	/** Minimum role required for each action, before ownership escalations. */
25	export const ROLE_MATRIX: Readonly<Record<PermissionAction, Role>> = {
26	  "org:read": "viewer",
27	  "org:update": "admin",
28	  "org:delete": "owner",
29	  "org:manage_billing": "owner",
30	  "org:manage_flags": "admin",
31	  "member:read": "viewer",
32	  "member:invite": "admin",
33	  "member:update_role": "admin",
34	  "member:remove": "admin",
35	  "project:create": "member",
36	  "project:read": "viewer",
37	  "project:update": "member",
38	  "project:archive": "admin",
39	  "project:delete": "owner",
40	  "issue:create": "member",
41	  "issue:read": "viewer",
42	  "issue:update": "member",
43	  "issue:assign": "member",
44	  "issue:archive": "member",
45	  "issue:delete": "admin",
46	  "comment:create": "member",
47	  "comment:read": "viewer",
48	  "comment:update": "member",
49	  "comment:delete": "admin",
50	  "activity:read": "member",
51	  "activity:export": "admin",
52	  "notification:read": "viewer",
53	  "notification:manage": "viewer",
54	  "webhook:manage": "admin",
55	};
56	
57	/** Actions an actor may perform on their own content regardless of role rank. */
58	const OWNERSHIP_ESCALATIONS: Readonly<Partial<Record<PermissionAction, true>>> = {
59	  "issue:update": true,
60	  "issue:archive": true,
61	  "comment:update": true,
62	  "comment:delete": true,
63	};
64	
65	/**
66	 * Actions that are personal regardless of role: no rank, however high, grants
67	 * access to someone else's resource. Only ownership (or staff) decides these.
68	 */
69	const OWNERSHIP_ONLY: Readonly<Partial<Record<PermissionAction, true>>> = {
70	  "notification:read": true,
71	  "notification:manage": true,
72	};
73	
74	function isOwnedByActor(
75	  actor: Actor,
76	  resource: PermissionResource,
77	): boolean {
78	  switch (resource.kind) {
79	    case "issue":
80	      return (
81	        resource.authorId === actor.userId ||
82	        resource.assigneeId === actor.userId
83	      );
84	    case "comment":
85	      return resource.authorId === actor.userId;
86	    case "project":
87	      return resource.leadId === actor.userId;
88	    case "notification":
89	      return resource.recipientId === actor.userId;
90	    case "member":
91	      return resource.targetUserId === actor.userId;
92	    default:
93	      return false;
94	  }
95	}
96	
97	/**
98	 * Answers "may this actor perform this action on this resource?".
99	 *
100	 * @param actor    the authenticated principal, always scoped to one org
101	 * @param action   a member of the closed `PermissionAction` vocabulary
102	 * @param resource the object being acted on, discriminated on `kind`
103	 */
104	export function can(
105	  actor: Actor,
106	  action: PermissionAction,
107	  resource: PermissionResource,
108	): boolean {
109	  return explain(actor, action, resource).allowed;
110	}
111	
112	/** Same decision as `can()`, but reports why — used by the settings UI. */
113	export function explain(
114	  actor: Actor,
115	  action: PermissionAction,
116	  resource: PermissionResource,
117	): PermissionDecision {
118	  const base = { action, resourceKind: resource.kind } as const;
119	
120	  if (actor.orgId !== resource.orgId) {
121	    return { ...base, allowed: false, reason: "denied_cross_tenant" };
122	  }
123	
124	  if (actor.isPlatformStaff === true) {
125	    return { ...base, allowed: true, reason: "granted_by_staff" };
126	  }
127	
128	  if (OWNERSHIP_ONLY[action] === true) {
129	    return isOwnedByActor(actor, resource)
130	      ? { ...base, allowed: true, reason: "granted_by_ownership" }
131	      : { ...base, allowed: false, reason: "denied_by_role" };
132	  }
133	
134	  const required = ROLE_MATRIX[action];
135	  if (required === undefined) {
136	    return { ...base, allowed: false, reason: "denied_unknown_action" };
137	  }
138	
139	  if (ROLE_RANK[actor.role] >= ROLE_RANK[required]) {
140	    return { ...base, allowed: true, reason: "granted_by_role" };
141	  }
142	
143	  if (OWNERSHIP_ESCALATIONS[action] === true && isOwnedByActor(actor, resource)) {
144	    return { ...base, allowed: true, reason: "granted_by_ownership" };
145	  }
146	
147	  return { ...base, allowed: false, reason: "denied_by_role" };
148	}
149	
150	/** Thrown by `assertCan()`; mapped to a `forbidden` `ActionResult` by callers. */
151	export class PermissionDeniedError extends Error {
152	  readonly code = "forbidden" as const;
153	
154	  constructor(
155	    readonly action: PermissionAction,
156	    readonly decision: PermissionDecision,
157	  ) {
158	    super(`Permission denied: ${action} on ${decision.resourceKind}`);
159	    this.name = "PermissionDeniedError";
160	  }
161	}
162	
163	/** Throwing variant of `can()` for service-layer guard clauses. */
164	export function assertCan(
165	  actor: Actor,
166	  action: PermissionAction,
